import React from 'react';

const paymentModal = ({ course, onClose }) => {
  if (!course) return null;
  return (
    <div className="fixed inset-0 bg-[#020617]/90 flex items-center justify-center z-50 p-4">
      <div className="bg-slate-950 p-8 rounded-xl border border-slate-800 w-full max-w-sm">
        <h2 className="text-white font-bold mb-2">{course.title}</h2>
        <p className="text-blue-400 font-mono mb-6">{course.price.toLocaleString()} FCFA</p>
        <button onClick={onClose} className="w-full bg-slate-800 text-white py-2 rounded">Fermer</button>
      </div>
    </div>
  );
};
export default paymentModal;
